public static String findTheLongestWord(String input) {
    String[] words = input.split("\s+"); String longest = ""; for (String word : words) if (word.length() > longest.length()) longest = word; return longest;
 }

public static String findTheLongestWord(String input) {
    return Arrays.stream(input.split("\s+")).reduce((longest, current) -> current.length() > longest.length() ? current : longest).orElse("");
 }
